// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

/**
 * Cost-vector and estimate-vector sanity invariants: an unknown (NaN / infinite / negative) component must never
 * saturate the whole plan cost into a {@code Double.MAX_VALUE} tie that hides the cost of the remaining, well-known
 * plan parts, and a filter can never produce more rows than its input.
 */
class CostVectorSaturationInvariantTest {

	private static final CostVector CHEAP_REST = new CostVector(10.0d, 10.0d, 0.0d, 5.0d, 0.0d, 1.0d, 1.0d);
	private static final CostVector HUGE_REST = new CostVector(1.0e12d, 1.0e12d, 0.0d, 0.0d, 0.0d, 1.0d, 1.0d);

	@Test
	void saturatedUnknownSubtreeMustNotHideElevenOrdersOfMagnitude() {
		CostVector unknown = new CostVector(Double.NaN, Double.NaN, 0.0d, 0.0d, 0.0d, 4.0d, 0.5d);
		assertCheapRestWins(unknown, "NaN");
	}

	@Test
	void infiniteUnknownSubtreeMustNotHideTheRestOfThePlan() {
		CostVector unknown = new CostVector(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY, 0.0d, 0.0d, 0.0d,
				4.0d, 0.5d);
		assertCheapRestWins(unknown, "+Infinity");
	}

	@Test
	void negativeUnknownSubtreeMustNotHideTheRestOfThePlan() {
		CostVector unknown = new CostVector(-1.0e9d, -1.0e9d, 0.0d, 0.0d, 0.0d, 4.0d, 0.5d);
		assertCheapRestWins(unknown, "negative");
	}

	@Test
	void unknownComponentsMustStayAdditive() {
		CostVector unknown = new CostVector(Double.NaN, Double.NaN, 0.0d, 0.0d, 0.0d, 4.0d, 0.5d);
		CostVector oneUnknown = unknown.plus(CHEAP_REST);
		CostVector twoUnknown = unknown.plus(unknown).plus(CHEAP_REST);
		assertTrue(oneUnknown.compareTo(twoUnknown) < 0,
				"one unknown subtree must be cheaper than two: one=" + oneUnknown.objectiveScore() + " two="
						+ twoUnknown.objectiveScore());
		assertTrue(Double.isFinite(twoUnknown.objectiveScore()) && Double.isFinite(twoUnknown.rows())
				&& Double.isFinite(twoUnknown.workRows()), "unknown components must keep a finite cost: " + twoUnknown);
	}

	@Test
	void objectiveScoreOfUnknownCostMustBeFinite() {
		CostVector unknown = new CostVector(Double.NaN, Double.NaN, Double.NaN, Double.NaN, Double.NaN, 4.0d, 0.5d);
		assertTrue(Double.isFinite(unknown.objectiveScore()) && unknown.objectiveScore() < Double.MAX_VALUE,
				"objective score must not saturate: " + unknown.objectiveScore());
		assertTrue(unknown.objectiveScore() > CHEAP_REST.objectiveScore(),
				"an unknown cost must still be pessimistic against a known cheap cost");
	}

	@Test
	void filterMustNeverRaiseTheUpperRowBound() {
		EstimateVector scan = EstimateVector.heuristic(100.0d, 4.0d, "scan");
		EstimateVector filtered = scan.filter(0.5d, null, "filter");
		assertTrue(filtered.upperRows() <= scan.upperRows(),
				"a filter cannot produce more rows than its input: input upper=" + scan.upperRows()
						+ " filtered upper=" + filtered.upperRows());
		assertTrue(filtered.rows() <= scan.rows(), "filtered point estimate must not exceed the input");
	}

	@Test
	void filterWithExplicitPassIntervalMustNeverRaiseTheUpperRowBound() {
		EstimateVector scan = EstimateVector.heuristic(100.0d, 4.0d, "scan");
		QErrorInterval optimisticPass = QErrorInterval.heuristic(0.9d, 4.0d, "learned-filter");
		EstimateVector filtered = scan.filter(0.9d, optimisticPass, "filter");
		assertTrue(filtered.upperRows() <= scan.upperRows(),
				"a filter with a learned pass interval cannot produce more rows than its input: input upper="
						+ scan.upperRows() + " filtered upper=" + filtered.upperRows());
		assertTrue(filtered.lowerRows() >= 0.0d && filtered.lowerRows() <= filtered.upperRows(),
				"filter bounds must stay ordered: [" + filtered.lowerRows() + "," + filtered.upperRows() + "]");
		assertEquals(filtered.upperRows() - filtered.lowerRows(), filtered.uncertaintyRows(), 1.0e-9d,
				"uncertainty must describe the clamped interval");
	}

	private static void assertCheapRestWins(CostVector unknown, String label) {
		CostVector cheapPlan = unknown.plus(CHEAP_REST);
		CostVector hugePlan = unknown.plus(HUGE_REST);
		assertTrue(cheapPlan.compareTo(hugePlan) < 0,
				label + " unknown+10 rows must beat unknown+1e12 rows; objective cheap=" + cheapPlan.objectiveScore()
						+ " huge=" + hugePlan.objectiveScore() + " compare=" + cheapPlan.compareTo(hugePlan));
	}
}
